type Trie struct {
	words map[string]bool
	index map[string]bool
}

func NewTriImpl() Trie {
	return Trie{
		words: make(map[string]bool, 0),
		index: make(map[string]bool, 0),
	}
}

func (t *Trie) Insert(word string) {
	t.words[word] = true
	prefix := ""
	for _, c := range word {
		prefix += string(c)
		t.index[prefix] = true
	}
}

func (t *Trie) Search(word string) bool {
	_, isExist := t.words[word]
	if isExist {
		return true
	}
	return false
}

func (t *Trie) StartsWith(prefix string) bool {
	_, isExist := t.index[prefix]
	if isExist {
		return true
	}
	return false
}

var trie Trie
var result []string

func wordBreak(s string, wordDict []string) []string {
	trie = NewTriImpl()
	for _, word := range wordDict {
		trie.Insert(word)
	}
	result = make([]string, 0)
	searchWord("", string(s[0]), s, 0)
	return result
}

func searchWord(curResult, prefix, word string, pos int) {
	if !trie.StartsWith(prefix) {
		return
	}
	if pos == len(word)-1 {
		if trie.Search(prefix) {
			result = append(result, strings.Trim(curResult+" "+prefix, " "))
		}
		return
	}
	if trie.Search(prefix) {
		searchWord(curResult+" "+prefix, string(word[pos+1]), word, pos+1)
	}
	searchWord(curResult, prefix+string(word[pos+1]), word, pos+1)
}

class Solution(object):
    def wordBreak(self, s, wordDict):
        self.tree = {}
        self.memo = {}
        for word in wordDict:
            self.buildNode(word, self.tree)
        self.splits = {}

        self.traverse(s, 0)

        return self.gen(s, len(s))

    def buildNode(self, word, tree):
        if not word:
            tree[-1] = True
        else:
            c = word[0]
            if c not in tree:
                tree[c] = {}
            self.buildNode(word[1:], tree[c])

    def gen(self, s, n):
        if n==0:
            return [""]
        results = []
        if not self.splits or n not in self.splits:
            return []
        for x in self.splits[n]:
            for ss in self.gen(s, x):
                if ss:
                    results.append(ss+" "+s[x:n])
                else:
                    results.append(s[x:n])
        return results

    def traverse(self, s, idx):
        if idx == len(s):
            return
        i = idx
        node = self.tree
        while True:
            if -1 in node:
                if i not in self.splits:
                    self.splits[i]=[idx]
                    self.traverse(s, i)
                elif idx not in self.splits[i]:
                    self.splits[i].append(idx)

            if i >= len(s):
                return
            else:
                c = s[i]
                if c in node:
                    node = node[c]
                    i = i+1
                else:
                    return

class Solution(object):
    def wordBreak(self, s, wordDict):
        """
        :type s: str
        :type wordDict: Set[str]
        :rtype: List[str]
        """
        if not wordDict:
            return False
        self.memo = {}
        self.maxlength = max([len(word) for word in wordDict]) 
        return self.recurse(s, wordDict)

    def recurse(self, s, wordDict):
        if not s:
            return [""]
        if s in self.memo:
            return self.memo[s]
        results = []
        for i in range(1, self.maxlength):
            if s[:i] in wordDict:
                sub = self.recurse(s[i:], wordDict)
                results += [s[:i]+" "+substr for substr in sub]
        self.memo = results
        return self.memo

# Dynamic programming
class Solution(object):
    def wordBreak(self, s, wordDict):
        """
        :type s: str
        :type wordDict: List[str]
        :rtype: List[str]
        """
        wordDict = set(wordDict)
        cache = {}

        def dfs(index):
            if index in cache:
                return cache[index]
            if index == len(s):
                return [[]]
            ans = []
            for i in range(index + 1, len(s) + 1):
                cur_word = s[index: i]
                if cur_word in wordDict:
                    new_ans = dfs(i)
                    for cur_new_ans in new_ans:
                        ans.append([cur_word] + cur_new_ans[:])
            cache[index] = ans
            return ans

        ans = dfs(0)
        return [" ".join(cur_ans) for cur_ans in ans]
